(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.012-t*0.18)*14;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.009+t*0.15)*10 + Math.cos((y+w1y)*0.011-t*0.12)*8;
  const w2y = Math.cos((y+w1y)*0.01-t*0.13)*9 + Math.sin((x+w1x)*0.008+t*0.17)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.5)*110, 60+Math.cos(t*0.35)*45, 0.07, 2.2, 1.0],
    [360+Math.cos(t*0.45)*100, 80+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.4+1)*100, 0.05, 2.6, 1.1],
    [80+Math.cos(t*0.7+1)*70, 180+Math.sin(t*0.5+3)*50, 0.11, 1.5, 0.85],
    [400+Math.sin(t*0.38+4)*80, 170+Math.cos(t*0.8+2)*60, 0.065, 2.4, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*70, 0.08, 2.0, 0.95],
    [180+Math.sin(t*0.55+3)*90, 40+Math.cos(t*0.42+4)*55, 0.075, 2.1, 0.9],
    [300+Math.cos(t*0.28+1)*100, 140+Math.sin(t*0.62+2)*65, 0.085, 1.9, 1.0]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,w]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.8)*w;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2]=src[j];
      const mx=(sX+sX2)/2+(sX2-sX)*Math.sin(t*0.4+i+j)*0.3;
      const my=(sY+sY2)/2+(sY2-sY)*Math.cos(t*0.35+i-j)*0.3;
      const dd=Math.sqrt((sx-mx)**2+(sy-my)**2);
      cross+=Math.sin(dd*0.12-t*1.8+i*0.7)*0.15;
    }
  }
  const n=src.length, act=aS/n, inh=iS/n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    +Math.sin((sx+sy)*0.11+t*2.2)*0.25+Math.sin((sx-sy)*0.09-t*1.8)*0.25
    +Math.sin(sx*0.06*Math.cos(t*0.2)+sy*0.05*Math.sin(t*0.15)+t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*5-t*1.0))*0.35;
  const spiral2=Math.sin(dist*0.02-ang*7+t*0.8)*0.2*Math.sin(dist*0.08+t*0.5);
  const turb=Math.sin(sx*0.08+t*1.5)*Math.cos(sy*0.07-t*1.2)*0.15;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+spiral2+cross+turb)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.07-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const fine=Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.08*Math.abs(reaction);
  const blend=reaction*0.65+cell*0.25+fine*0.1, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,35,88],[18,72,118],[24,118,128],[45,158,130],
    [120,180,100],[195,185,70],[218,148,60],[210,105,65],[185,65,72],
    [130,38,68],[75,22,58],[40,15,55],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.78+Math.sin(reaction*Math.PI)*0.22;
  const edge=Math.abs(reaction)>0.72?1.18:Math.abs(reaction)>0.5?1.06:1.0;
  const glow=Math.max(0,Math.abs(reaction)-0.6)*0.4;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*25)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0
  ];
}
